import { expect, test, type Page } from "@playwright/test";
import { existsSync } from "node:fs";
import path from "node:path";
import { launchPackagedApp, type LaunchedApp } from "./launch";

// Generated by `npm run fixtures`: an 8 s vertical clip.
const CLIP = path.resolve("fixtures", "vertical_1080x1920_30.mp4");
const FULL = "Levi's 501 Jeans";
const SHORT = "the 501s";
const BANK_TEXT = "{product} changed my whole wardrobe";
const RESOLVED = "the 501s changed my whole wardrobe";

let launched: LaunchedApp;
let page: Page;

test.beforeAll(async () => {
  test.skip(!existsSync(CLIP), 'Run "npm run fixtures" first.');
  launched = await launchPackagedApp();
  page = await launched.app.firstWindow();
});

test.afterAll(async () => {
  await launched?.app.close();
});

type SavedClip = {
  zoom: string;
  muted: boolean;
  caption: {
    text: string;
    sourceCaptionId?: string;
    style: string;
    position: string;
  } | null;
};

// What autosave wrote to the database: the "before" clip of the open draft.
async function savedBefore(): Promise<SavedClip> {
  return page.evaluate(async () => {
    const id = await window.api.settings.getOpenDraft();
    const video = await window.api.videos.get(id as string);
    return JSON.parse((video as { recipeJson: string }).recipeJson).clips[0];
  });
}

const bank = () =>
  page.evaluate(async () =>
    (await window.api.captions.list()).map((c) => ({
      id: c.id,
      text: c.text,
      slot: c.slot,
      productId: c.productId,
    })),
  );

// The lines the preview draws, joined: outline style draws every line twice (stroke layer
// and fill layer), so only the fill-layer / box text nodes carry the test id.
const drawnText = async () =>
  (await page.getByTestId("caption-line").allTextContents())
    .join(" ")
    .replace(/\s+/g, " ")
    .trim();

test("clip controls: zoom, mute, captions, look, warning, save to bank", async () => {
  let productId = "";
  let originalId = "";

  await test.step("set up a product with a short name, one bank caption and a before clip", async () => {
    await page.getByRole("button", { name: "Choose another folder" }).click();
    await page.getByRole("button", { name: "Use this folder" }).click();
    await page.getByRole("button", { name: "Add your first product" }).click();
    const dialog = page.getByRole("dialog", { name: "Add product" });
    await dialog.getByLabel("Full name").fill(FULL);
    await dialog.getByLabel("Short name").fill(SHORT);
    await dialog.getByRole("button", { name: "Add product" }).click();
    await expect(dialog).toBeHidden();

    const ids = await page.evaluate(
      async ({ text }) => {
        const [product] = await window.api.products.list();
        const created = await window.api.captions.create({
          text,
          slot: "before",
          productId: product.id,
        });
        if (!created.ok) {
          throw new Error(created.message);
        }
        return { productId: product.id, captionId: created.value.id };
      },
      { text: BANK_TEXT },
    );
    productId = ids.productId;
    originalId = ids.captionId;

    await page
      .getByRole("button", { name: "New Video", exact: true })
      .first()
      .click();
    await page.getByRole("option", { name: new RegExp(FULL) }).click();
    await page.getByLabel("Before clip file").setInputFiles([CLIP]);
    await expect(page.getByTestId("slot-before")).toHaveAttribute(
      "data-status",
      "ready",
      { timeout: 90_000 },
    );
    await page
      .getByTestId("slot-before")
      .getByRole("heading", { name: "Before" })
      .click();
    await expect(page.getByTestId("caption-section")).toBeVisible();
    // No caption yet: the look controls wait for one.
    await expect(page.getByTestId("caption-style-box")).toBeDisabled();
  });

  await test.step("picking a caption resolves {product} to the short name", async () => {
    await page.getByTestId("caption-pick").click();
    const picker = page.getByRole("dialog", { name: "Choose a caption" });
    await picker.getByRole("option", { name: new RegExp(RESOLVED) }).click();
    await expect(picker).toBeHidden();

    await expect(page.getByTestId("caption-text")).toHaveValue(RESOLVED);
    await expect
      .poll(async () => (await savedBefore()).caption)
      .toEqual({
        text: RESOLVED,
        sourceCaptionId: originalId,
        style: "outline",
        position: "middle",
      });
    // The preview draws it (fill-layer lines only, not the stroke copies).
    await expect.poll(drawnText).toBe(RESOLVED);
    await expect(page.getByTestId("caption-svg")).toBeVisible();
  });

  await test.step("editing the text changes the draft, never the bank", async () => {
    const edited = `${RESOLVED}, honestly`;
    await page.getByTestId("caption-text").fill(edited);
    await expect
      .poll(async () => (await savedBefore()).caption?.text)
      .toBe(edited);
    // Still remembered as started from the picked caption.
    expect((await savedBefore()).caption?.sourceCaptionId).toBe(originalId);
    await expect.poll(drawnText).toBe(edited);
    expect(await bank()).toEqual([
      expect.objectContaining({ id: originalId, text: BANK_TEXT }),
    ]);
  });

  await test.step("Save to bank prefills slot, product and a tokenized text", async () => {
    await page.getByTestId("caption-save").click();
    const dialog = page.getByRole("dialog", { name: "Add caption" });
    await expect(dialog.getByLabel("Text")).toHaveValue(
      "{product} changed my whole wardrobe, honestly",
    );
    await expect(dialog.getByLabel("Slot")).toHaveValue("before");
    await expect(dialog.getByLabel("Product")).toHaveValue(productId);
    await expect(dialog.getByTestId("caption-form-preview")).toContainText(
      `${RESOLVED}, honestly`,
    );
    await dialog.getByRole("button", { name: "Add caption" }).click();
    await expect(dialog).toBeHidden();
    await expect(page.getByTestId("caption-saved")).toBeVisible();

    const rows = await bank();
    expect(rows).toHaveLength(2);
    // The original is unchanged; the new row holds the token, not the baked-in name.
    expect(rows.find((r) => r.id === originalId)?.text).toBe(BANK_TEXT);
    const created = rows.find((r) => r.id !== originalId)!;
    expect(created).toMatchObject({
      text: "{product} changed my whole wardrobe, honestly",
      slot: "before",
      productId,
    });
    // The caption now starts from the new row.
    await expect
      .poll(async () => (await savedBefore()).caption?.sourceCaptionId)
      .toBe(created.id);
  });

  await test.step("style and position apply to the preview and the recipe", async () => {
    await page.getByTestId("caption-style-box").click();
    await page.getByTestId("caption-position-top").click();
    await expect
      .poll(async () => (await savedBefore()).caption)
      .toMatchObject({ style: "box", position: "top" });
    await expect(page.getByTestId("caption-style-box")).toHaveAttribute(
      "aria-checked",
      "true",
    );
    await expect.poll(drawnText).toBe(`${RESOLVED}, honestly`);
    // Box style draws white rects behind the text.
    await expect(
      page.getByTestId("caption-svg").locator("rect"),
    ).not.toHaveCount(0);
  });

  await test.step("zoom and mute", async () => {
    expect(await savedBefore()).toMatchObject({ zoom: "none", muted: false });
    await page.getByTestId("zoom-toggle").click();
    await page.getByTestId("mute-toggle").click();
    await expect(page.getByTestId("zoom-toggle")).toHaveAttribute(
      "aria-checked",
      "true",
    );
    await expect
      .poll(savedBefore)
      .toMatchObject({ zoom: "slow-push", muted: true });
    await page.getByTestId("zoom-toggle").click();
    await expect.poll(savedBefore).toMatchObject({ zoom: "none", muted: true });
  });

  await test.step("a very long caption warns, a short one does not", async () => {
    await expect(page.locator('[data-testid^="caption-warning"]')).toHaveCount(
      0,
    );
    await page
      .getByTestId("caption-text")
      .fill(
        "this caption keeps going and going because the creator had so much to say about how these jeans changed everything for them this year",
      );
    await expect(
      page.locator('[data-testid^="caption-warning"]'),
    ).toBeVisible();
    await page.getByTestId("caption-text").fill("4 weeks later");
    await expect(page.locator('[data-testid^="caption-warning"]')).toHaveCount(
      0,
    );
  });

  await test.step("clear caption removes it; the bank keeps both rows", async () => {
    await page.getByTestId("caption-clear").click();
    await expect.poll(async () => (await savedBefore()).caption).toBeNull();
    await expect(page.getByTestId("caption-text")).toHaveValue("");
    await expect(page.getByTestId("caption-line")).toHaveCount(0);
    expect(await bank()).toHaveLength(2);
  });

  await test.step("a new caption copies the look of the other slots", async () => {
    // Typing creates a caption with the default look (no other slot has one now).
    await page.getByTestId("caption-text").fill("typed by hand");
    await expect
      .poll(async () => (await savedBefore()).caption)
      .toEqual({ text: "typed by hand", style: "outline", position: "middle" });
  });
});
